def krr_cv(X, y, gamma, lam, kind='rbf', k=5, seed=0):
    n=len(y); S=np.zeros((n,8))
    for te in folds(n,k,seed,y):
        tr=np.setdiff1d(np.arange(n),te)
        mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6
        Z=(X-mu)/sd; Z/=np.sqrt(Z.shape[1])
        if kind=='rbf':
            sq=(Z**2).sum(1)
            K=np.exp(-gamma*(sq[:,None]+sq[None,:]-2*Z@Z.T))
        elif kind=='poly':
