        Ktr=K[np.ix_(tr,tr)]
        T=np.eye(8)[y[tr]]; tm=T.mean(0)
        a=np.linalg.solve(Ktr+lam*np.eye(len(tr)), T-tm)
        S[te]=K[np.ix_(te,tr)]@a+tm
    return (S.argmax(1)==y).mean()
