        rng=np.random.default_rng(rs)
        if kind=='center':
            Cc=Z[rng.choice(tr,nunits,replace=False)]; 
            Hf=np.tanh(scale*Z@Cc.T)
        else:
            Wr=rng.standard_normal((X.shape[1],nunits)); bb=rng.uniform(-1,1,nunits)
            Hf=np.tanh(scale*Z@Wr+bb)
