            sq=(Z**2).sum(1); Hf=np.exp(-gamma*np.maximum(sq[:,None]+(Cc**2).sum(1)[None]-2*Z@Cc.T,0))
        elif feat=='exp': Hf=np.exp(2*gamma*Z@Cc.T)
        elif feat=='tanh': Hf=np.tanh(gamma*Z@Cc.T+bias)+1
