    n=len(y); S=np.zeros((n,8))
    for te in folds(n,k,seed,y):
        tr=np.setdiff1d(np.arange(n),te)
        Zs=[zs(X,tr)*(1 if weights is None else w) for X,w in zip(blocks, weights or [1]*len(blocks))]
        Z=np.concatenate(Zs,1)/np.sqrt(len(blocks)); sq=(Z**2).sum(1)
