def add_cv(kb, lin, y, gammas, cs, lams, seeds=(0,1,2), k=5):
    n=len(y); res={}
    for s in seeds:
        for te in folds(n,k,s,y):
            tr=np.setdiff1d(np.arange(n),te)
            Z=zs(kb,tr); sq=(Z**2).sum(1); D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0)
            ZL=np.concatenate([zs(X,tr) for X in lin],1)/np.sqrt(len(lin)) if lin else None
            KL=ZL@ZL.T if lin else 0
            T=np.eye(8)[y[tr]]-1/8
            for g in gammas:
                KR=np.exp(-g*D2)
                for c in cs:
                    K=KR+c*KL; w,V=np.linalg.eigh(K[np.ix_(tr,tr)]); R=V.T@T; Kte=K[np.ix_(te,tr)]
                    for l in lams:
                        key=(g,c,l); pred=(Kte@(V@(R/(w+l)[:,None]))).argmax(1)
                        res.setdefault(key,[0,0]); res[key][0]+=(pred==y[te]).sum(); res[key][1]+=len(te)
    return {k_:round(v[0]/v[1],4) for k_,v in res.items()}
