def zsall(X): mu=X.mean(0); sd=X.std(0)+1e-6; return (X-mu)/sd/np.sqrt(X.shape[1])
def loo(blocks, y, gammas=(0.2,0.4,0.8), lams=(0.001,0.003,0.01,0.03), lin=None, c=0.3):
    Z=np.concatenate([zsall(X) for X in blocks],1)/np.sqrt(len(blocks)); sq=(Z**2).sum(1)
    D2=np.maximum(sq[:,None]+sq[None]-2*Z@Z.T,0); T=np.eye(8)[y]-1/8; out={}
    KL = 0 if lin is None else (lambda ZL: ZL@ZL.T)(np.concatenate([zsall(X) for X in lin],1)/np.sqrt(len(lin)))
    for g in gammas:
        K=np.exp(-g*D2)+c*KL; w,V=np.linalg.eigh(K)
        for l in lams:
            Hd=((V**2)*(w/(w+l))[None]).sum(1); Yh=V@((w/(w+l))[:,None]*(V.T@T))
            Yloo=(Yh-Hd[:,None]*T)/(1-Hd[:,None])
            out[(g,l)]=round(((Yloo).argmax(1)==y).mean(),4)
    return out
