def zs(Xtr, Xte=None):
    mu = Xtr.mean(0); sd = Xtr.std(0)+1e-6
    return ((Xtr-mu)/sd, None if Xte is None else (Xte-mu)/sd)
def rbf(A, B, gamma):
    d = A.shape[1]
    A2=(A**2).sum(1)[:,None]; B2=(B**2).sum(1)[None]
    D = np.maximum(A2+B2-2*A@B.T, 0)/d
    return np.exp(-gamma*D)
